//! Investigation only: real native providers, charged small fixture sink, no store.
use cpg_extract::{acquisition::{AcquiredInput, Acquisition, Acquire, LibraryInventory, InventoryDistribution, InventoryFile}, bundle::{CapturedInputs, ProviderSink, ProviderStage, run_provider}, capture::CapturedInput};
use lctx_model::domain::{*, batching::TransferLimits, resources::ResourceBudget, stages::{Profile, ProviderOutcome}};
use std::{any::Any, collections::BTreeMap, sync::{Arc, Mutex}};
struct Sink { data: Mutex<BTreeMap<&'static str, Box<dyn Any+Send+Sync>>>, bodies: Mutex<BTreeMap<&'static str, Vec<String>>>, model:Arc<ValidatedModel>, budget:ResourceBudget }
impl Sink { fn new(model:Arc<ValidatedModel>,budget:ResourceBudget)->Self {Self{data:Default::default(),bodies:Default::default(),model,budget}} fn snapshot(&self)->BTreeMap<&'static str,Vec<String>> {self.bodies.lock().unwrap().iter().map(|(name,rows)|{let mut rows=rows.clone();rows.sort();rows.dedup();(*name,rows)}).collect()} }
impl ProviderSink for Sink {
 fn declare<R:Record>(&self)->Result<(),ModelError> {self.data.lock().unwrap().entry(R::NAME).or_insert_with(||Box::new(Vec::<Batch<R>>::new())); self.bodies.lock().unwrap().entry(R::NAME).or_default(); Ok(())}
 fn write<R:Record>(&self,batch:Batch<R>)->Result<(),ModelError> {self.declare::<R>()?; let _debug=self.budget.reserve("probe-debug-copy",batch.rows().iter().map(|r|r.row_bytes().saturating_mul(32).saturating_add(4096)).sum())?;let mut bodies=self.bodies.lock().unwrap();let rows=bodies.get_mut(R::NAME).unwrap();for row in batch.rows(){let body=format!("{row:?}");assert!(body.len()<1<<20);rows.push(body);}assert!(bodies.values().flatten().map(String::len).sum::<usize>()<32<<20);drop(bodies);self.data.lock().unwrap().get_mut(R::NAME).unwrap().downcast_mut::<Vec<Batch<R>>>().unwrap().push(batch);Ok(())}
 fn contribute<R:Record>(&self,batch:Batch<R>)->Result<(),ModelError>{self.write(batch)}
 fn read<R:Record>(&self)->Result<Box<dyn Iterator<Item=Result<Batch<R>,ModelError>>+Send>,ModelError>{let data=self.data.lock().unwrap();let batches=data.get(R::NAME).ok_or_else(||ModelError::Invalid(format!("missing {}",R::NAME)))?.downcast_ref::<Vec<Batch<R>>>().unwrap();let mut rows:Vec<R>=batches.iter().flat_map(|b|b.rows().iter().cloned()).collect();rows.sort_by_key(Record::id);rows.dedup();let batches=rows.chunks(97).map(|rows|Batch::new(&self.model,rows.to_vec(),&self.budget)).collect::<Vec<_>>();Ok(Box::new(batches.into_iter()))}
 fn finish(&self,_:ProviderOutcome)->Result<(),ModelError>{Ok(())}
}
#[derive(Clone,Copy)] enum Variant{Simple,SimpleReverse,Empty,Base,Reverse,Label,InstalledBase,Role,Record,Settings,Cycle}
async fn population(v:Variant,profile:Profile)->(BTreeMap<&'static str,Vec<String>>,Vec<ProviderOutcome>,ContentHash,ContentHash,ContentHash){
 let budget=ResourceBudget::fixed(1<<30).unwrap();let model=Arc::new(model().unwrap()); let original=tempfile::tempdir().unwrap();
 let files=if matches!(v,Variant::Simple|Variant::SimpleReverse){[("a.py","x = 1\n"),("b.py","")]}else if matches!(v,Variant::Empty){[("a.py",""),("b.py","")]}else{[("a.py","from b import f\nx = f(3)\ndef inherited(n: int):\n    return n\n"),("b.py",if matches!(v,Variant::Cycle){"from a import inherited\ndef f(n):\n    return inherited(n)\n"}else{"def f(n):\n    return n\n"})]};
 for (name,source) in files {std::fs::write(original.path().join(name),source).unwrap();}
 let mut paths=vec!["a.py".into(),"b.py".into()];if matches!(v,Variant::Reverse|Variant::SimpleReverse){paths.reverse();}
 let captured=CapturedInput::capture(original.path(),&paths,&budget).unwrap();
 let acquisition=if matches!(v,Variant::InstalledBase|Variant::Role|Variant::Record){Acquisition::Installed(LibraryInventory{name:"probe".into(),requirement:"==1.0".into(),lock_digest:ContentHash::of(b"lock"),installer:Some("uv".into()),python_version:"3.14.7".into(),platform:"linux".into(),site_packages:original.path().to_owned(),distributions:vec![InventoryDistribution{name:"probe".into(),version:"1.0".into(),first_party:true,artifact_sha256:vec![],record_digest:ContentHash::of(if matches!(v,Variant::Record){b"record-b"}else{b"record-a"})}],files:paths.iter().map(|path|InventoryFile{path:path.clone(),owners:vec!["probe".into()],role:if matches!(v,Variant::Role){lctx_model::domain::input::SourceRole::Dependency}else{lctx_model::domain::input::SourceRole::Release},record_sha256:None}).collect(),configuration:ContentHash::of(b"acquire")})}else{Acquisition::Tree{label:if matches!(v,Variant::Label){"changed"}else{"probe"}.into()}};
 let mut settings=cpg_extract::ruff_context::ContextSettings::default();if matches!(v,Variant::Settings){settings.custom_builtins=vec!["probe_builtin".into()];}
 let config=cpg_extract::native_context::NativeContextConfig::committed(profile,&budget).unwrap().with_ruff(settings).unwrap();let cfg=config.digest();let inputs=Arc::new(CapturedInputs::new(vec![AcquiredInput::new(captured,acquisition)],config));
 let binding=ContentHash::of(format!("{:?}",cpg_extract::contracts::captured_sources(&inputs).unwrap()).as_bytes()); let sink=Arc::new(Sink::new(model.clone(),budget.clone()));let mut providers:Vec<Box<dyn ProviderStage<Sink>>>=vec![Box::new(Acquire::new(ContentHash::of(b"acquire"))),Box::new(cpg_extract::pyrefly_stage::Pyrefly::new(Default::default())),Box::new(cpg_extract::document_parser::Documents),Box::new(cpg_extract::deployment::Deployment),Box::new(cpg_extract::assembly::Assemble)];if profile==Profile::Behavioral{providers.push(Box::new(cpg_extract::ty_flow::TyFlow::default()));}
 let mut acquisition=ContentHash::of(b"unset");let mut outcomes=vec![];for provider in providers {outcomes.push(run_provider(provider,profile,sink.clone(),model.clone(),inputs.clone(),budget.clone(),TransferLimits{rows:if matches!(v,Variant::Reverse|Variant::SimpleReverse){1}else{97},..Default::default()}).await.unwrap());if outcomes.len()==1{acquisition=ContentHash::of(format!("{:?}",sink.snapshot()).as_bytes());}}
 (sink.snapshot(),outcomes,cfg,binding,acquisition)
}
#[tokio::test] async fn actual_native_population_decisions(){let mut acquire=None;for profile in Profile::ALL {let (base,outcomes,cfg,binding,acquisition)=population(Variant::Base,profile).await;let (repeat,again,_,_,_)=population(Variant::Base,profile).await;if let Some(prior)=acquire{assert_eq!(prior,acquisition);}else{acquire=Some(acquisition);}let (simple_rows,simple,_,_,_)=population(Variant::Simple,profile).await;let (simple_reverse,simple_outcomes,_,_,_)=population(Variant::SimpleReverse,profile).await;assert_eq!(simple_rows,simple_reverse);assert_eq!(simple,simple_outcomes);let (_,empty,_,_,_)=population(Variant::Empty,profile).await;println!("{} minimal constant {:?}; empty source {:?}",profile.name(),simple,empty);assert_eq!(empty[1],if profile==Profile::Catalog{ProviderOutcome::Complete}else{ProviderOutcome::Partial});assert_eq!(simple[1],empty[1]);assert_eq!(base,repeat);assert_eq!(outcomes,again);let (reverse,reordered,_,_,_)=population(Variant::Reverse,profile).await;assert_eq!(base,reverse);assert_eq!(outcomes,reordered);println!("{} stable complete typed population: {} declared relations, {} rows; outcomes {:?}",profile.name(),base.len(),base.values().map(Vec::len).sum::<usize>(),outcomes);for (variant,name) in [(Variant::Label,"origin"),(Variant::Settings,"settings"),(Variant::Cycle,"import-cycle")] {let (changed,_,changed_cfg,changed_binding,_)=population(variant,profile).await;assert_ne!(base,changed,"{name}");if name=="settings"{assert_ne!(cfg,changed_cfg);}if name=="origin"{assert_eq!(binding,changed_binding);println!("PD01 current CapturedSourceBinding misses origin change");}println!("{} {name} changes complete typed population",profile.name());}let (a,_,_,record_binding,_)=population(Variant::InstalledBase,profile).await;let (role,_,_,role_binding,_)=population(Variant::Role,profile).await;assert_ne!(a,role);assert_eq!(record_binding,role_binding);println!("{} same-byte same-origin role changes population",profile.name());let (b,_,_,new_record_binding,_)=population(Variant::Record,profile).await;assert_ne!(a,b);assert_eq!(record_binding,new_record_binding);println!("{} same-byte RECORD attribution changes population",profile.name());}}

#[test]
fn portable_value_and_not_requested_contract_boundaries(){
 use lctx_model::domain::compilation_product::*;
 let request=ProductRequest{kind:ProductKind::PureRows,operation:"probe".into(),model:ContentHash::of(b"model"),implementation:ContentHash::of(b"implementation"),policy:ContentHash::of(b"policy"),result_contract:ContentHash::of(b"contract"),configuration:None,profile:"catalog".into(),parameters:vec![],dependencies:vec![DependencyToken{kind:DependencyKind::ExactView,role:"source".into(),relation:"source".into(),prefix:None,identity:ContentHash::of(b"exact-a")}],outputs:std::collections::BTreeSet::from(["rows".into()])};
 let a=PortableProduct{request,outcome:ProductOutcome::Complete,sections:vec![ProductSection{name:"rows".into(),rows:1,bytes:br#"[{"source":"old-source-id","score":1}]"#.to_vec()}]};let mut b=a.clone();b.request.dependencies[0].identity=ContentHash::of(b"exact-b");assert_eq!(a.value_identity().unwrap(),b.value_identity().unwrap());assert_ne!(a.identity().unwrap(),b.identity().unwrap());b.sections[0].bytes=br#"[{"source":"new-source-id","score":1}]"#.to_vec();assert_ne!(a.value_identity().unwrap(),b.value_identity().unwrap());
 assert!(lctx_model::domain::admission::reconcile(ProviderOutcome::NotRequested,&[]).is_err());assert!(lctx_model::domain::admission::reconcile(ProviderOutcome::Complete,&[]).is_ok());println!("actual PortableProduct value identity keeps section source IDs; model rejects generic NotRequested reconciliation");
}
